import React, { useState, useEffect, useRef } from 'react';
import { Helmet } from 'react-helmet';
import { useParams } from 'react-router-dom';
import { collection, getDocs, query, where, doc, getDoc, addDoc } from 'firebase/firestore';
import { db } from './firebase';
import './JobLandingPage.css';
import { 
  FaUser, 
  FaEnvelope, 
  FaPhone, 
  FaFileAlt, 
  FaPaperclip, 
  FaBriefcase, 
  FaLocationArrow,
  FaCheckCircle,
  FaBuilding,
  FaMapMarkerAlt
} from 'react-icons/fa';

// Hjälpfunktion för att bestämma enhetstyp
function getDeviceType(userAgent) {
  if (/tablet|ipad|playbook|silk/i.test(userAgent)) {
    return "tablet";
  } else if (/Mobile|Android|iPhone|iPod/i.test(userAgent)) {
    return "phone";
  }
  return "desktop";
}

function JobLandingPage() {
  const { jobId } = useParams();
  const [job, setJob] = useState(null);
  const [company, setCompany] = useState(null);
  const [loading, setLoading] = useState(true);
  const formRef = useRef(null);
  const [cv, setCv] = useState(null);
  const [personalLetter, setPersonalLetter] = useState(null);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '' });
  const [errorMessage, setErrorMessage] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [showPrivacyPolicy, setShowPrivacyPolicy] = useState(false);

  // Screening-relaterad state
  const [screenAnswers, setScreenAnswers] = useState([]);
  const [currentStep, setCurrentStep] = useState(0);
  const [screenStepCompleted, setScreenStepCompleted] = useState(false);
  const [computedRating, setComputedRating] = useState(0);

  const defaultCompanyImageUrl = "https://via.placeholder.com/150";

  useEffect(() => {
    const fetchJobAndCompany = async () => {
      try {
        const jobsQuery = query(collection(db, 'jobs'), where('jobId', '==', jobId));
        const jobSnapshot = await getDocs(jobsQuery);
        if (!jobSnapshot.empty) {
          const jobData = jobSnapshot.docs[0].data();
          setJob(jobData);
          if (jobData.companyId) {
            try {
              const companyRef = doc(db, 'companies', jobData.companyId);
              const companySnap = await getDoc(companyRef);
              if (companySnap.exists()) {
                setCompany(companySnap.data());
              } else {
                setCompany({
                  name: jobData.companyName || "Okänt företag",
                  imageUrl: jobData.companyImageUrl || defaultCompanyImageUrl
                });
              }
            } catch (error) {
              console.error("Fel vid hämtning av företag:", error.message);
              setCompany({
                name: jobData.companyName || "Okänt företag",
                imageUrl: jobData.companyImageUrl || defaultCompanyImageUrl
              });
            }
          }
        }
      } catch (err) {
        console.error('Fel vid hämtning av jobb:', err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchJobAndCompany();
  }, [jobId]);

  // Initiera screening-svar. Om inga screen questions finns visas formuläret direkt med rating 0.
  useEffect(() => {
    if (job) {
      if (job.screenQuestions && job.screenQuestions.length > 0) {
        setScreenAnswers(new Array(job.screenQuestions.length).fill(''));
        setCurrentStep(0);
        setScreenStepCompleted(false);
        setComputedRating(0);
      } else {
        setScreenStepCompleted(true);
        setComputedRating(0);
      }
    }
  }, [job]);

  // Logga besöket – nu sparas även deviceType
  useEffect(() => {
    if (job) {
      const logVisit = async () => {
        try {
          const deviceType = getDeviceType(navigator.userAgent);
          const docRef = await addDoc(collection(db, 'pageVisits'), {
            jobId: job.jobId,
            companyId: job.companyId,
            timestamp: new Date().toISOString(),
            referrer: document.referrer || 'direct',
            userAgent: navigator.userAgent,
            deviceType
          });
          console.log("Besöksdokument skapat med ID:", docRef.id);
        } catch (error) {
          console.error("Fel vid loggning av besök:", error);
        }
      };
      logVisit();
    }
  }, [job]);

  const handleFileUpload = (event, setFile) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onloadend = () => {
        setFile({ name: file.name, data: reader.result });
      };
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Hantera svar på screening-frågor via Ja/Nej-knappar
  const handleScreenAnswer = (answer) => {
    const newAnswers = [...screenAnswers];
    newAnswers[currentStep] = answer;
    setScreenAnswers(newAnswers);
    if (currentStep === job.screenQuestions.length - 1) {
      let validCount = 0;
      let correctCount = 0;
      for (let i = 0; i < job.screenQuestions.length; i++) {
        const question = job.screenQuestions[i];
        if (question.question && question.expectedAnswer && question.expectedAnswer.trim() !== '') {
          validCount++;
          if (
            newAnswers[i] &&
            newAnswers[i].trim().toLowerCase() === question.expectedAnswer.trim().toLowerCase()
          ) {
            correctCount++;
          }
        }
      }
      const rating = validCount > 0 ? (correctCount / validCount) * 5 : 0;
      const roundedRating = Math.round(rating * 2) / 2;
      setComputedRating(roundedRating);
      setScreenStepCompleted(true);
    } else {
      setCurrentStep(currentStep + 1);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.phone) {
      setErrorMessage('Fyll i alla obligatoriska fält.');
      return;
    }
    try {
      await addDoc(collection(db, 'applications'), {
        name: formData.name,
        name_lower: formData.name.toLowerCase(),
        email: formData.email,
        phone: formData.phone,
        jobTitle: job?.title || 'Okänt jobb',
        jobId: jobId,
        companyId: job?.companyId || 'Okänt företag',
        cv: cv ? cv : null,
        personalLetter: personalLetter ? personalLetter : null,
        date: new Date().toISOString(),
        referrer: document.referrer || 'direct',
        deviceType: getDeviceType(navigator.userAgent),
        contacted: false,
        interview: false,
        disqualified: false,
        hired: false,
        opened: false,
        rating: computedRating,
        // EXTRA: Lägger till screening-svar om jobb har screenQuestions
        screenAnswers: job.screenQuestions && job.screenQuestions.length > 0 ? screenAnswers : []
      });
      setSubmitted(true);
      setErrorMessage('');
      setFormData({ name: '', email: '', phone: '' });
      setCv(null);
      setPersonalLetter(null);
    } catch (error) {
      console.error('Fel vid skicka ansökan:', error);
      setErrorMessage('Kunde inte skicka ansökan.');
    }
  };

  const scrollToForm = () => {
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const heroBackground = job && job.customColors ? (() => {
    const colors = [];
    if (job.customColors.customColor1Active && job.customColors.customColor1) colors.push(job.customColors.customColor1);
    if (job.customColors.customColor2Active && job.customColors.customColor2) colors.push(job.customColors.customColor2);
    if (job.customColors.customColor3Active && job.customColors.customColor3) colors.push(job.customColors.customColor3);
    if (colors.length === 0) {
      return "linear-gradient(135deg, #0a2342, #17365d, #1e4e79)";
    }
    if (colors.length === 1) {
      return colors[0];
    }
    return `linear-gradient(135deg, ${colors.join(', ')})`;
  })() : "linear-gradient(135deg, #0a2342, #17365d, #1e4e79)";

  const heroStyle = { background: heroBackground };

  return (
    <div className="job-landing-page">
      <Helmet>
        <title>{company && job ? `${company.name} - ${job.title}` : "QwioJobs"}</title>
      </Helmet>
      <div className="hero" style={heroStyle}>
        {loading ? (
          <div className="loading-spinner"></div>
        ) : (
          <>
            {company?.imageUrl && (
              <img src={company.imageUrl} alt={company.name} className="company-banner" />
            )}
            <h1>{job?.title || "Jobb hittades inte"}</h1>
            {job?.location && (
              <div className="job-location">
                <FaLocationArrow className="location-icon" /> <span className="location-text">{job.location}</span>
              </div>
            )}
            <p className="published-by">Publicerat av {company?.name || "Okänt företag"}</p>
            <button className="apply-button" onClick={scrollToForm}>Ansök nu</button>
          </>
        )}
      </div>

      {!loading && job && (
        <>
          <div className="job-description">
            <FaBriefcase className="job-icon" />
            <div
              className="job-description-content"
              dangerouslySetInnerHTML={{ __html: job?.description || "Ingen beskrivning tillgänglig" }}
            />
          </div>

          <div className="application-form-container" ref={formRef}>
            {submitted ? (
              <div className="application-success">
                <FaCheckCircle className="success-icon" />
                <h2>Tack för din ansökan!</h2>
                <p>Du har nu skickat in din ansökan.</p>
              </div>
            ) : (
              <>
                {/* Application header visas alltid */}
                <div className="application-header">
                  <div className="header-badge">
                    <FaCheckCircle className="badge-icon" /> Enkel och snabb ansökan
                  </div>
                  <h2 className="header-title">Ansök till jobbet!</h2>
                  <div className="header-details">
                    <div className="header-line">
                      <FaBriefcase className="header-icon" />
                      <span className="form-job-title">{job?.title}</span>
                    </div>
                    <div className="header-line">
                      <FaMapMarkerAlt className="header-icon" />
                      <span className="form-job-location">{job?.location}</span>
                    </div>
                    <div className="header-line">
                      <FaBuilding className="header-icon" />
                      <span className="form-company-name">{company?.name}</span>
                    </div>
                  </div>
                </div>

                {job.screenQuestions && job.screenQuestions.length > 0 && !screenStepCompleted ? (
                  <div className="screening-step">
                    {/* Banner för aktuellt steg */}
                    <div className="screening-step-banner">Steg {currentStep + 1}</div>
                    <h3>{job.screenQuestions[currentStep].question}</h3>
                    <div className="yes-no-buttons">
                      <button className="yes-button" onClick={() => handleScreenAnswer("ja")}>Ja</button>
                      <button className="no-button" onClick={() => handleScreenAnswer("nej")}>Nej</button>
                    </div>
                  </div>
                ) : (
                  <div className={`form-fields ${screenStepCompleted ? 'visible' : ''}`}>
                    <form className="application-form" onSubmit={handleSubmit}>
                      <div className="input-group">
                        <FaUser className="input-icon" />
                        <input
                          type="text"
                          name="name"
                          placeholder="Fullständigt namn *"
                          value={formData.name}
                          onChange={handleChange}
                          required
                        />
                      </div>
                      <div className="input-group">
                        <FaEnvelope className="input-icon" />
                        <input
                          type="email"
                          name="email"
                          placeholder="E-postadress *"
                          value={formData.email}
                          onChange={handleChange}
                          required
                        />
                      </div>
                      <div className="input-group">
                        <FaPhone className="input-icon" />
                        <input
                          type="tel"
                          name="phone"
                          placeholder="Telefonnummer *"
                          value={formData.phone}
                          onChange={handleChange}
                          required
                        />
                      </div>
                      <div className="input-group file-upload">
                        <FaPaperclip className="input-icon" />
                        <input 
                          type="file" 
                          accept=".pdf,.doc,.docx" 
                          onChange={(e) => handleFileUpload(e, setCv)} 
                        />
                        <label>
                          {cv 
                            ? cv.name 
                            : <>Bifoga CV <span className="optional-tag">(Valfritt)</span></>
                          }
                        </label>
                      </div>
                      <div className="input-group file-upload">
                        <FaFileAlt className="input-icon" />
                        <input 
                          type="file" 
                          accept=".pdf,.doc,.docx" 
                          onChange={(e) => handleFileUpload(e, setPersonalLetter)} 
                        />
                        <label>
                          {personalLetter 
                            ? personalLetter.name 
                            : <>Bifoga Personligt Brev <span className="optional-tag">(Valfritt)</span></>
                          }
                        </label>
                      </div>
                      <div className="privacy-policy-text">
                        <p>
                          När du skickar in ansökan godkänner du{' '}
                          <a href="#!" onClick={(e) => { e.preventDefault(); setShowPrivacyPolicy(true); }}>
                            Integritetspolicyn
                          </a>{' '}
                          samt att {company?.name || "företaget"} lagrar dina uppgifter för att hantera din ansökan.
                        </p>
                      </div>
                      <button type="submit" className="submit-button">Skicka ansökan</button>
                    </form>
                    {errorMessage && <p className="error-message">{errorMessage}</p>}
                  </div>
                )}
              </>
            )}
          </div>
        </>
      )}

      {/* Popup för integritetspolicyn med extra klass för unik styling */}
      {showPrivacyPolicy && (
        <div className="popup-overlay" onClick={() => setShowPrivacyPolicy(false)}>
          <div className="popup privacy-policy" onClick={(e) => e.stopPropagation()}>
            <span className="popup-close" onClick={() => setShowPrivacyPolicy(false)}>×</span>
            <h2>Integritetspolicy</h2>
            <p>
              Vi på {company?.name || "companyName"} värnar om din integritet och behandlar dina personuppgifter med största respekt. När du skickar in din ansökan via vårt formulär samlar vi in och behandlar dina personuppgifter i egenskap av personuppgiftsansvarig. Detta inkluderar:
            </p>
            <ul>
              <li>Förnamn</li>
              <li>Efternamn</li>
              <li>E-postadress</li>
              <li>Telefonnummer</li>
              <li>Bifogade filer (CV och personligt brev)</li>
            </ul>
            <p>
            <strong>Syfte och laglig grund för behandlingen</strong><br />
              Vi behandlar dina personuppgifter för att kunna hantera rekryteringsprocessen på ett säkert och effektivt sätt. Dina uppgifter används uteslutande för att:
            </p>
            <ul>
              <li>Utvärdera din ansökan</li>
              <li>Kontakta dig angående en intervju eller annan relevant information om rekryteringsprocessen</li>
            </ul>
            <p>
              Den lagliga grunden för vår behandling är vårt berättigade intresse av att administrera rekryteringsprocessen och kommunicera med dig som kandidat. Om vi behöver spara dina uppgifter längre än den aktuella rekryteringen kommer vi att be om ditt samtycke, vilket du när som helst kan återkalla.
            </p>
            <p>
              <strong>Teknisk data och trafikkälla</strong><br />
              För att förbättra användarupplevelsen och optimera våra tjänster samlar vi även in teknisk information om den enhet du använder, såsom:
            </p>
            <ul>
              <li>Enhetstyp, webbläsare, operativsystem och liknande tekniska parametrar</li>
              <li>Information om trafikkälla, dvs. vilken webbplats eller källa du kom ifrån när du hamnade på vår landningssida</li>
            </ul>
            <p>
              Dessa uppgifter används för att analysera besöksmönster, förbättra vår webbplats och säkerställa att tjänsten fungerar optimalt. Behandlingen av denna tekniska data grundar sig på vårt berättigade intresse.
            </p>
            <p>
              <strong>Lagring och radering av uppgifter</strong><br />
              Dina uppgifter sparas i upp till 2 år efter avslutad rekrytering för att vi ska kunna kontakta dig vid framtida möjligheter. Efter denna period raderas dina uppgifter på ett säkert sätt, om vi inte har fått ditt samtycke till fortsatt lagring.
            </p>
            <p>
              <strong>Vem har tillgång till dina uppgifter?</strong><br />
              Eftersom varje rekryteringsannons publiceras av ett specifikt företag ansvarar det rekryterande företaget för hanteringen av dina personuppgifter, i detta fall {company?.name || "companyName"}. Qwio Group AB agerar som personuppgiftsbiträde och hanterar dina uppgifter enligt instruktioner från det ansvariga företaget samt i enlighet med gällande lagstiftning.
            </p>
            <p>
              <strong>Dina rättigheter enligt GDPR</strong><br />
              Du har rätt att:
            </p>
            <ul>
              <li>Begära tillgång till de personuppgifter vi behandlar om dig</li>
              <li>Begära rättelse av felaktiga eller ofullständiga uppgifter</li>
              <li>Begära att vi raderar dina uppgifter (under vissa förutsättningar)</li>
              <li>Begära att vi begränsar behandlingen av dina uppgifter</li>
              <li>Invända mot att vi behandlar dina uppgifter</li>
              <li>Begära att få ut dina uppgifter i ett strukturerat, allmänt använt och maskinläsbart format (dataportabilitet)</li>
            </ul>
            <p>
              Lämna in ett klagomål till Integritetsskyddsmyndigheten (IMY) om du anser att vi hanterar dina personuppgifter på ett sätt som strider mot GDPR.
            </p>
            <p>
            För frågor om dina personuppgifter eller för att utöva dina rättigheter, vänligen kontakta det rekryterande företaget, {company?.name || "companyName"}.
            </p>
            <p>
              <strong>Genom att skicka in din ansökan godkänner du att {company?.name || "companyName"} lagrar och behandlar dina personuppgifter enligt denna policy.</strong>
            </p>
          </div>
        </div>
      )}

      <footer className="footer">
        <p>© {new Date().getFullYear()} QwioJobs. Alla rättigheter förbehållna.</p>
      </footer>
    </div>
  );
}

export default JobLandingPage;
