import React, { useState, useEffect } from 'react';
import { collection, getDocs, query, where, updateDoc, deleteDoc, doc, setDoc } from 'firebase/firestore';
import { createUserWithEmailAndPassword } from 'firebase/auth';
import { db, auth } from './firebase';
import './ManageUsers.css';

// Enkel modal-komponent
function Modal({ children, onClose }) {
  return (
    <div className="mu-modal-overlay">
      <div className="mu-modal">
        <button className="mu-modal-close" onClick={onClose}>×</button>
        {children}
      </div>
    </div>
  );
}

function ManageUsers() {
  const [companies, setCompanies] = useState([]);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const [users, setUsers] = useState([]);
  const [editingUser, setEditingUser] = useState(null);
  const [newUser, setNewUser] = useState({ name: '', email: '', password: '', role: 'user' });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Modal-states
  const [showAddUserModal, setShowAddUserModal] = useState(false);
  const [showEditUserModal, setShowEditUserModal] = useState(false);
  const [showDeleteUserModal, setShowDeleteUserModal] = useState(false);
  const [userToDelete, setUserToDelete] = useState(null);

  // Hämta företagen vid sidladdning
  useEffect(() => {
    const fetchCompanies = async () => {
      try {
        const snapshot = await getDocs(collection(db, 'companies'));
        setCompanies(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
      } catch (err) {
        setError('Kunde inte hämta företagsdata.');
      }
    };
    fetchCompanies();
  }, []);

  // Hämta användare för valt företag
  const fetchUsers = async (companyId) => {
    setSelectedCompany(companyId);
    setError('');
    setSuccess('');
    try {
      const usersSnapshot = await getDocs(query(collection(db, 'users'), where('companyId', '==', companyId)));
      setUsers(usersSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    } catch (err) {
      setError('Kunde inte hämta användardata.');
    }
  };

  // Lägg till användare (via modal)
  const handleAddUser = async (e) => {
    e.preventDefault(); // Förhindra siduppdatering
    if (!selectedCompany || !newUser.email || !newUser.password || !newUser.name || !newUser.role) {
      setError('Alla fält måste fyllas i.');
      return;
    }
    if (newUser.password.length < 6) {
      setError('Lösenordet måste vara minst 6 tecken långt.');
      return;
    }
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, newUser.email, newUser.password);
      const userId = userCredential.user.uid;
      await setDoc(doc(db, 'users', userId), {
        uid: userId,
        email: newUser.email,
        name: newUser.name,
        role: newUser.role,
        companyId: selectedCompany
      });
      fetchUsers(selectedCompany);
      setNewUser({ name: '', email: '', password: '', role: 'user' });
      setSuccess('Användare har lagts till.');
      setShowAddUserModal(false);
    } catch (err) {
      console.error(err);
      setError('Kunde inte lägga till användaren. Kontrollera att e-postadressen är giltig och att lösenordet uppfyller kraven.');
    }
  };

  // Öppna edit-modal för användare
  const openEditUserModal = (user) => {
    setEditingUser(user);
    setShowEditUserModal(true);
    setError('');
    setSuccess('');
  };

  // Spara redigering av användare (via modal)
  const handleEditUser = async () => {
    if (!editingUser.name || !editingUser.role) {
      setError('Fyll i alla fält.');
      return;
    }
    try {
      await updateDoc(doc(db, 'users', editingUser.id), {
        name: editingUser.name,
        role: editingUser.role
      });
      setUsers(users.map(user => user.id === editingUser.id ? { ...user, name: editingUser.name, role: editingUser.role } : user));
      setEditingUser(null);
      setShowEditUserModal(false);
      setSuccess('Användaren har uppdaterats.');
    } catch (err) {
      console.error(err);
      setError('Kunde inte uppdatera användaren.');
    }
  };

  // Öppna delete-modal för användare
  const openDeleteUserModal = (user) => {
    setUserToDelete(user);
    setShowDeleteUserModal(true);
  };

  // Bekräfta radering av användare (via modal)
  const confirmDeleteUser = async () => {
    if (!userToDelete) return;
    try {
      await deleteDoc(doc(db, 'users', userToDelete.id));
      setUsers(users.filter(user => user.id !== userToDelete.id));
      setShowDeleteUserModal(false);
      setUserToDelete(null);
      setSuccess('Användaren har tagits bort.');
    } catch (err) {
      console.error(err);
      setError('Kunde inte ta bort användaren.');
    }
  };

  // Avbryt redigering (stäng edit-modal)
  const handleCancelEdit = () => {
    setShowEditUserModal(false);
    setEditingUser(null);
    setError('');
  };

  return (
    <div className="mu-manage-users" id="mu-manage-users">
      <h1 id="mu-title">Hantera Användare</h1>
      {error && <p className="mu-error-message" id="mu-error-message">{error}</p>}
      {success && <p className="mu-success-message" id="mu-success-message">{success}</p>}

      <div className="mu-company-grid">
        {companies.map(company => (
          <div key={company.id} className="mu-company-card">
            <h3>{company.name}</h3>
            <button className="mu-btn mu-select-btn" onClick={() => fetchUsers(company.id)}>
              Hantera Användare
            </button>
          </div>
        ))}
      </div>

      {selectedCompany && (
        <div className="mu-user-management">
          <h2>Användare i företaget</h2>
          <ul className="mu-user-list">
            {users.map(user => (
              <li key={user.id} className="mu-user-item">
                <span>{user.name} ({user.role})</span>
                <div className="mu-user-actions">
                  <button className="mu-btn mu-edit-btn" onClick={() => openEditUserModal(user)}>✏️</button>
                  <button className="mu-btn mu-delete-btn" onClick={() => openDeleteUserModal(user)}>❌</button>
                </div>
              </li>
            ))}
          </ul>
          <button className="mu-btn mu-add-user-btn" onClick={() => setShowAddUserModal(true)}>
            Lägg till ny användare
          </button>
        </div>
      )}

      {showAddUserModal && (
        <Modal onClose={() => setShowAddUserModal(false)}>
          <h2>Lägg till ny användare</h2>
          <form className="mu-add-user-form" onSubmit={handleAddUser}>
            <input
              type="text"
              placeholder="Fullständigt namn"
              value={newUser.name}
              onChange={(e) => setNewUser({ ...newUser, name: e.target.value })}
            />
            <input
              type="email"
              placeholder="E-post"
              value={newUser.email}
              onChange={(e) => setNewUser({ ...newUser, email: e.target.value })}
            />
            <input
              type="password"
              placeholder="Lösenord"
              value={newUser.password}
              onChange={(e) => setNewUser({ ...newUser, password: e.target.value })}
            />
            <select
              value={newUser.role}
              onChange={(e) => setNewUser({ ...newUser, role: e.target.value })}
            >
              <option value="user">User</option>
              <option value="admin">Admin</option>
            </select>
            <div className="mu-button-group">
              <button type="submit" className="mu-btn">Lägg till användare</button>
              <button type="button" className="mu-btn mu-cancel-btn" onClick={() => setShowAddUserModal(false)}>Avbryt</button>
            </div>
          </form>
        </Modal>
      )}

      {showEditUserModal && editingUser && (
        <Modal onClose={handleCancelEdit}>
          <h2>Redigera användare</h2>
          <div className="mu-form-group">
            <label htmlFor="mu-edit-name">Fullständigt namn:</label>
            <input
              type="text"
              id="mu-edit-name"
              className="mu-input"
              value={editingUser.name}
              onChange={(e) => setEditingUser({ ...editingUser, name: e.target.value })}
            />
          </div>
          <div className="mu-form-group">
            <label htmlFor="mu-edit-role">Roll:</label>
            <select
              id="mu-edit-role"
              className="mu-input"
              value={editingUser.role}
              onChange={(e) => setEditingUser({ ...editingUser, role: e.target.value })}
            >
              <option value="user">User</option>
              <option value="admin">Admin</option>
            </select>
          </div>
          <div className="mu-button-group">
            <button className="mu-btn mu-save-btn" onClick={handleEditUser}>Spara</button>
            <button className="mu-btn mu-cancel-btn" onClick={handleCancelEdit}>Avbryt</button>
          </div>
        </Modal>
      )}

      {showDeleteUserModal && userToDelete && (
        <Modal onClose={() => setShowDeleteUserModal(false)}>
          <h2>Bekräfta radering</h2>
          <p>Är du säker på att du vill ta bort denna användare?</p>
          <div className="mu-button-group">
            <button className="mu-btn mu-delete-btn" onClick={confirmDeleteUser}>Ja</button>
            <button className="mu-btn mu-cancel-btn" onClick={() => setShowDeleteUserModal(false)}>Nej</button>
          </div>
        </Modal>
      )}
    </div>
  );
}

export default ManageUsers;
