import React, { useState, useEffect, useCallback } from 'react';
import { collection, getDocs, query, where, getCountFromServer } from 'firebase/firestore';
import { db } from './firebase';
import {
  FaBriefcase,
  FaCalendarDay,
  FaCalendarMinus,
  FaCalendarWeek,
  FaCalendarAlt,
  FaCalendar,
  FaChartBar
} from 'react-icons/fa';
import './DashboardStats.css';

// Hjälpfunktioner
function isSameDay(date1, date2) {
  return (
    date1.getFullYear() === date2.getFullYear() &&
    date1.getMonth() === date2.getMonth() &&
    date1.getDate() === date2.getDate()
  );
}

function getWeekNumber(d) {
  d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

function isSameWeek(date1, date2) {
  return (
    date1.getFullYear() === date2.getFullYear() &&
    getWeekNumber(date1) === getWeekNumber(date2)
  );
}

function getInitials(nameOrEmail) {
  if (!nameOrEmail) return "";
  const parts = nameOrEmail.trim().split(" ");
  return parts.length >= 2
    ? parts[0].charAt(0).toUpperCase() + parts[1].charAt(0).toUpperCase()
    : nameOrEmail.substring(0, 2).toUpperCase();
}

function DashboardStats({ user }) {
  const [stats, setStats] = useState({
    published: 0,
    today: 0,
    yesterday: 0,
    thisWeek: 0,
    thisMonth: 0,
    thisYear: 0,
    total: 0,
  });
  const [statusStats, setStatusStats] = useState({
    hired: 0,
    disqualified: 0,
    contacted: 0,
    interview: 0,
    opened: 0,
  });
  const [loading, setLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState(null);
  const [selectedPeriod, setSelectedPeriod] = useState('today');
  const [userStats, setUserStats] = useState(null);
  const [companyMembers, setCompanyMembers] = useState([]);
  const [deviceStats, setDeviceStats] = useState(null);
  const [allowedJobIds, setAllowedJobIds] = useState([]);

  useEffect(() => {
    async function fetchStats() {
      try {
        let jobsQuery;
        if (user.role !== 'admin') {
          jobsQuery = query(
            collection(db, 'jobs'),
            where('companyId', '==', user.companyId),
            where('allowedMembers', 'array-contains', user.uid)
          );
        } else {
          jobsQuery = query(
            collection(db, 'jobs'),
            where('companyId', '==', user.companyId)
          );
        }
        const publishedJobsSnapshot = await getCountFromServer(jobsQuery);
        const publishedJobs = publishedJobsSnapshot.data().count;
        
        const jobsDocsSnapshot = await getDocs(jobsQuery);
        const jobIds = jobsDocsSnapshot.docs.map(doc => doc.data().jobId || doc.id);
        setAllowedJobIds(jobIds);

        if (jobIds.length === 0) {
          setStats({
            published: 0,
            today: 0,
            yesterday: 0,
            thisWeek: 0,
            thisMonth: 0,
            thisYear: 0,
            total: 0,
          });
          setStatusStats({
            hired: 0,
            disqualified: 0,
            contacted: 0,
            interview: 0,
            opened: 0,
          });
          setLoading(false);
          return;
        }

        // Datumgränser
        const now = new Date();
        const startToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const startTomorrow = new Date(startToday);
        startTomorrow.setDate(startTomorrow.getDate() + 1);
        const startYesterday = new Date(startToday);
        startYesterday.setDate(startYesterday.getDate() - 1);
        const endYesterday = new Date(startYesterday);
        endYesterday.setDate(endYesterday.getDate() + 1);
        const dayOfWeek = startToday.getDay();
        const diffToMonday = (dayOfWeek + 6) % 7;
        const startOfWeek = new Date(startToday);
        startOfWeek.setDate(startOfWeek.getDate() - diffToMonday);
        const endOfWeek = new Date(startOfWeek);
        endOfWeek.setDate(endOfWeek.getDate() + 7);
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
        const startOfYear = new Date(now.getFullYear(), 0, 1);
        const endOfYear = new Date(now.getFullYear() + 1, 0, 1);

        const getCount = async (queryRef) => {
          const snapshot = await getCountFromServer(queryRef);
          return snapshot.data().count;
        };

        const chunkArray = (arr, chunkSize) => {
          const chunks = [];
          for (let i = 0; i < arr.length; i += chunkSize) {
            chunks.push(arr.slice(i, i + chunkSize));
          }
          return chunks;
        };
        const queryInChunks = async (baseQueryGenerator) => {
          let total = 0;
          const chunks = chunkArray(jobIds, 10);
          for (const chunk of chunks) {
            const q = baseQueryGenerator(chunk);
            total += await getCount(q);
          }
          return total;
        };

        const totalApplications = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids)
          );
        });
        const countToday = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('date', '>=', startToday.toISOString()),
            where('date', '<', startTomorrow.toISOString())
          );
        });
        const countYesterday = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('date', '>=', startYesterday.toISOString()),
            where('date', '<', endYesterday.toISOString())
          );
        });
        const countThisWeek = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('date', '>=', startOfWeek.toISOString()),
            where('date', '<', endOfWeek.toISOString())
          );
        });
        const countThisMonth = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('date', '>=', startOfMonth.toISOString()),
            where('date', '<', endOfMonth.toISOString())
          );
        });
        const countThisYear = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('date', '>=', startOfYear.toISOString()),
            where('date', '<', endOfYear.toISOString())
          );
        });

        const countHired = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('hired', '==', true)
          );
        });
        const countDisqualified = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('disqualified', '==', true)
          );
        });
        const countContacted = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('contacted', '==', true)
          );
        });
        const countInterview = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('interview', '==', true)
          );
        });
        const countOpened = await queryInChunks((ids) => {
          return query(
            collection(db, 'applications'),
            where('jobId', 'in', ids),
            where('opened', '==', true)
          );
        });

        setStats({
          published: publishedJobs,
          today: countToday,
          yesterday: countYesterday,
          thisWeek: countThisWeek,
          thisMonth: countThisMonth,
          thisYear: countThisYear,
          total: totalApplications,
        });
        setStatusStats({
          hired: countHired,
          disqualified: countDisqualified,
          contacted: countContacted,
          interview: countInterview,
          opened: countOpened,
        });
        setLoading(false);
      } catch (error) {
        console.error('Fel vid hämtning av statistik:', error);
        setLoading(false);
      }
    }
    fetchStats();
  }, [user.companyId, user.uid, user.role]);

  useEffect(() => {
    async function fetchDeviceStats() {
      if (allowedJobIds.length === 0) {
        setDeviceStats({ desktop: 0, phone: 0, tablet: 0 });
        return;
      }
      try {
        const chunkArray = (arr, chunkSize) => {
          const chunks = [];
          for (let i = 0; i < arr.length; i += chunkSize) {
            chunks.push(arr.slice(i, i + chunkSize));
          }
          return chunks;
        };
        const queryInChunks = async (baseQueryGenerator) => {
          let total = 0;
          const chunks = chunkArray(allowedJobIds, 10);
          for (const chunk of chunks) {
            const q = baseQueryGenerator(chunk);
            const snapshot = await getCountFromServer(q);
            total += snapshot.data().count;
          }
          return total;
        };

        const phoneCount = await queryInChunks((ids) => {
          return query(
            collection(db, 'pageVisits'),
            where('companyId', '==', user.companyId),
            where('jobId', 'in', ids),
            where('deviceType', '==', 'phone')
          );
        });
        const tabletCount = await queryInChunks((ids) => {
          return query(
            collection(db, 'pageVisits'),
            where('companyId', '==', user.companyId),
            where('jobId', 'in', ids),
            where('deviceType', '==', 'tablet')
          );
        });
        const desktopCount = await queryInChunks((ids) => {
          return query(
            collection(db, 'pageVisits'),
            where('companyId', '==', user.companyId),
            where('jobId', 'in', ids),
            where('deviceType', '==', 'desktop')
          );
        });
        setDeviceStats({ phone: phoneCount, tablet: tabletCount, desktop: desktopCount });
      } catch (error) {
        console.error("Error fetching device stats:", error);
      }
    }
    fetchDeviceStats();
  }, [user.companyId, allowedJobIds]);

  useEffect(() => {
    if (user.role === 'admin') {
      async function fetchCompanyMembers() {
        try {
          const membersQuery = query(
            collection(db, 'users'),
            where('companyId', '==', user.companyId)
          );
          const snapshot = await getDocs(membersQuery);
          const members = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
          setCompanyMembers(members);
        } catch (error) {
          console.error("Fel vid hämtning av företagsmedlemmar:", error.message);
        }
      }
      fetchCompanyMembers();
    }
  }, [user.companyId, user.role]);

  const calcPercentage = (count) => {
    return stats.total > 0 ? ((count / stats.total) * 100).toFixed(0) : 0;
  };

  const loadUserStats = useCallback(async (userId, period) => {
    let openedCount = 0, contactedCount = 0, bookedCount = 0, disqualifiedCount = 0, hiredCount = 0;
    const now = new Date();
    const isToday = (date) => isSameDay(date, now);
    const isYesterday = (date) => {
      const yesterday = new Date(now);
      yesterday.setDate(now.getDate() - 1);
      return isSameDay(date, yesterday);
    };
    const isThisWeek = (date) => isSameWeek(date, now);
    const isThisMonth = (date) =>
      date.getMonth() === now.getMonth() && date.getFullYear() === now.getFullYear();

    try {
      const appsQuery = query(
        collection(db, 'applications'),
        where('companyId', '==', user.companyId)
      );
      const snapshot = await getDocs(appsQuery);
      snapshot.forEach(doc => {
        const data = doc.data();
        const logs = data.activityLog || [];
        logs.forEach(entry => {
          if (entry.userId === userId) {
            const entryDate = new Date(entry.timestamp);
            let matches = false;
            if (period === 'today') matches = isToday(entryDate);
            else if (period === 'yesterday') matches = isYesterday(entryDate);
            else if (period === 'week') matches = isThisWeek(entryDate);
            else if (period === 'month') matches = isThisMonth(entryDate);
            else if (period === 'total') matches = true;
            if (matches) {
              const lowerMsg = entry.message.toLowerCase();
              if (lowerMsg.includes("öppnades")) openedCount++;
              if (lowerMsg.includes("kontaktad")) contactedCount++;
              if (lowerMsg.includes("bokad")) bookedCount++;
              if (lowerMsg.includes("ej kvalificerad")) disqualifiedCount++;
              if (lowerMsg.includes("anställd")) hiredCount++;
            }
          }
        });
      });
      setUserStats({
        opened: openedCount,
        contacted: contactedCount,
        booked: bookedCount,
        disqualified: disqualifiedCount,
        hired: hiredCount
      });
    } catch (error) {
      console.error("Fel vid hämtning av user stats:", error);
    }
  }, [user.companyId]);

  useEffect(() => {
    if (selectedUser) {
      loadUserStats(selectedUser.id, selectedPeriod);
    }
  }, [selectedUser, selectedPeriod, loadUserStats]);

  // Beräkna procent baserat på deviceStats
  let totalDevices = 0;
  let desktopPercent = 0;
  let phonePercent = 0;
  let tabletPercent = 0;
  if (deviceStats) {
    totalDevices = deviceStats.desktop + deviceStats.phone + deviceStats.tablet;
    desktopPercent = totalDevices > 0 ? Math.round((deviceStats.desktop / totalDevices) * 100) : 0;
    phonePercent = totalDevices > 0 ? Math.round((deviceStats.phone / totalDevices) * 100) : 0;
    tabletPercent = totalDevices > 0 ? Math.round((deviceStats.tablet / totalDevices) * 100) : 0;
  }

  // Använd deviceStats-procent för att skapa en gradient för enhetsdiagrammet
  const devicePieGradient = `conic-gradient(
    #4caf50 0% ${desktopPercent}%,
    #2196f3 ${desktopPercent}% ${desktopPercent + phonePercent}%,
    #ff9800 ${desktopPercent + phonePercent}% ${desktopPercent + phonePercent + tabletPercent}%
  )`;

  return (
    <div className="dashboard-stats-container">
      {loading ? (
        <div className="loading-spinner">
          <div className="spinner"></div>
        </div>
      ) : (
        <>
          <div className="stats-grid">
            <div className="stat-card">
              <div className="icon-container">
                <FaBriefcase />
              </div>
              <h3>Publicerade jobb</h3>
              <p>{stats.published}</p>
            </div>
            <div className="stat-card">
              <div className="icon-container">
                <FaCalendarDay />
              </div>
              <h3>Ansökningar idag</h3>
              <p>{stats.today}</p>
            </div>
            <div className="stat-card">
              <div className="icon-container">
                <FaCalendarMinus />
              </div>
              <h3>Ansökningar igår</h3>
              <p>{stats.yesterday}</p>
            </div>
            <div className="stat-card">
              <div className="icon-container">
                <FaCalendarWeek />
              </div>
              <h3>Ansökningar denna vecka</h3>
              <p>{stats.thisWeek}</p>
            </div>
            <div className="stat-card">
              <div className="icon-container">
                <FaCalendarAlt />
              </div>
              <h3>Ansökningar denna månad</h3>
              <p>{stats.thisMonth}</p>
            </div>
            <div className="stat-card">
              <div className="icon-container">
                <FaCalendar />
              </div>
              <h3>Ansökningar i år</h3>
              <p>{stats.thisYear}</p>
            </div>
            <div className="stat-card total">
              <div className="icon-container">
                <FaChartBar />
              </div>
              <h3>Totala ansökningar</h3>
              <p>{stats.total}</p>
            </div>
          </div>

          <div className="device-stats-section">
            <div className="device-stats-header">
              <lord-icon
                src="https://cdn.lordicon.com/ibstvmps.json"
                trigger="loop"
                delay="1500"
                style={{ width: "100px", height: "100px", marginRight: "10px" }}
              ></lord-icon>
              <h2>Device Insights</h2>
            </div>
            <p className="device-stats-subtitle">
              Total statistik för användningen av enheter på de publicerade jobbsidorna
            </p>
            {deviceStats && (
              <div className="pie-chart-container">
                <div className="pie-chart" style={{ background: devicePieGradient }}></div>
                <div className="pie-chart-legend">
                  <div>
                    <span className="legend-color" style={{ background: '#4caf50' }}></span> 
                    Desktop: {desktopPercent}%
                  </div>
                  <div>
                    <span className="legend-color" style={{ background: '#2196f3' }}></span> 
                    Phone: {phonePercent}%
                  </div>
                  <div>
                    <span className="legend-color" style={{ background: '#ff9800' }}></span> 
                    Tablet: {tabletPercent}%
                  </div>
                </div>
              </div>
            )}
          </div>

          {user.role === 'admin' && (
            <>
              <div className="chart-container">
                <h2>Insights</h2>
                <div className="chart">
                  <div className="chart-bar">
                    <span className="chart-label">Anställa</span>
                    <div className="bar-wrapper">
                      <div
                        className="bar bar-hired"
                        style={{ width: `${calcPercentage(statusStats.hired)}%` }}
                      ></div>
                      <span className="bar-value">{calcPercentage(statusStats.hired)}%</span>
                    </div>
                  </div>
                  <div className="chart-bar">
                    <span className="chart-label">Ej kvalificerad</span>
                    <div className="bar-wrapper">
                      <div
                        className="bar bar-disqualified"
                        style={{ width: `${calcPercentage(statusStats.disqualified)}%` }}
                      ></div>
                      <span className="bar-value">{calcPercentage(statusStats.disqualified)}%</span>
                    </div>
                  </div>
                  <div className="chart-bar">
                    <span className="chart-label">Kontaktad</span>
                    <div className="bar-wrapper">
                      <div
                        className="bar bar-contacted"
                        style={{ width: `${calcPercentage(statusStats.contacted)}%` }}
                      ></div>
                      <span className="bar-value">{calcPercentage(statusStats.contacted)}%</span>
                    </div>
                  </div>
                  <div className="chart-bar">
                    <span className="chart-label">Bokade intervjuer</span>
                    <div className="bar-wrapper">
                      <div
                        className="bar bar-interview"
                        style={{ width: `${calcPercentage(statusStats.interview)}%` }}
                      ></div>
                      <span className="bar-value">{calcPercentage(statusStats.interview)}%</span>
                    </div>
                  </div>
                  <div className="chart-bar">
                    <span className="chart-label">Öppnade ansökningar</span>
                    <div className="bar-wrapper">
                      <div
                        className="bar bar-opened"
                        style={{ width: `${calcPercentage(statusStats.opened)}%` }}
                      ></div>
                      <span className="bar-value">{calcPercentage(statusStats.opened)}%</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="user-insights">
                <div className="user-insights-header">
                  <lord-icon
                    src="https://cdn.lordicon.com/fmdwwfgs.json"
                    trigger="loop"
                    delay="1000"
                    style={{ width: '100px', height: '100px' }}
                  ></lord-icon>
                  <h2>Userinsights</h2>
                </div>
                <p className="user-insights-subtitle">
                  Klicka på en användare för att se detaljerad statistik
                </p>
                <ul className="user-list">
                  {companyMembers
                    .filter(member => member.role !== 'admin')
                    .map(member => (
                      <li
                        key={member.id}
                        className="user-item"
                        onClick={() => setSelectedUser(member)}
                      >
                        <div className="insights-avatar">
                          {getInitials(member.name || member.email)}
                        </div>
                        <div className="insights-name">
                          {member.name || member.email}
                        </div>
                      </li>
                    ))}
                </ul>
              </div>
            </>
          )}
        </>
      )}

      {selectedUser && (
        <div className="modal-overlay" onClick={() => { setSelectedUser(null); setUserStats(null); }}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h3>{selectedUser.name || selectedUser.email}</h3>
            <div className="tabs">
              <button
                className={selectedPeriod === 'today' ? 'active' : ''}
                onClick={() => setSelectedPeriod('today')}
              >
                Idag
              </button>
              <button
                className={selectedPeriod === 'yesterday' ? 'active' : ''}
                onClick={() => setSelectedPeriod('yesterday')}
              >
                Igår
              </button>
              <button
                className={selectedPeriod === 'week' ? 'active' : ''}
                onClick={() => setSelectedPeriod('week')}
              >
                Vecka
              </button>
              <button
                className={selectedPeriod === 'month' ? 'active' : ''}
                onClick={() => setSelectedPeriod('month')}
              >
                Månad
              </button>
              <button
                className={selectedPeriod === 'total' ? 'active' : ''}
                onClick={() => setSelectedPeriod('total')}
              >
                Totalt
              </button>
            </div>
            {userStats ? (
              <ul className="user-stats">
                <li>Öppnade ansökningar: {userStats.opened}</li>
                <li>Kontaktade kandidater: {userStats.contacted}</li>
                <li>Bokade intervjuer: {userStats.booked}</li>
                <li>Ej kvalificerade: {userStats.disqualified}</li>
                <li>Anställda: {userStats.hired}</li>
              </ul>
            ) : (
              <div>Hämtar statistik...</div>
            )}
            <button className="close-button" onClick={() => { setSelectedUser(null); setUserStats(null); }}>
              Stäng
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default DashboardStats;
