import React, { useState, useEffect } from 'react';
import './Dashboard.css';
import SuperAdminDashboard from './SuperAdminDashboard';
import PublishedJobs from './PublishedJobs';
import JobApplications from './JobApplications';
import DashboardStats from './DashboardStats';
import ManageCompanies from './ManageCompanies';
import ManageUsers from './ManageUsers';
import Settings from './Settings';
import SuperSettings from './SuperSettings'; 
import { FaBars, FaTimes, FaBell } from 'react-icons/fa';
import { collection, query, where, limit, onSnapshot } from 'firebase/firestore';
import { db } from './firebase';
import vitLogo from '../img/vit.png';

function Dashboard({ user, handleLogout }) {
  const isSuperAdmin = user.role === 'superadmin';
  const isAdmin = user.role === 'admin';
  const isUser = user.role === 'user';

  const [selectedMenu, setSelectedMenu] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Istället för att räkna exakt antal nya ansökningar, håller vi en boolesk flagga:
  const [hasNewApplications, setHasNewApplications] = useState(false);

  // Realtidslyssnare som endast läser in ett dokument (om det finns någon matchande ny ansökan)
  useEffect(() => {
    if (user.companyId) {
      const notificationsQuery = query(
        collection(db, 'applications'),
        where('companyId', '==', user.companyId),
        where('opened', '==', false),
        where('contacted', '==', false),
        where('interview', '==', false),
        where('disqualified', '==', false),
        where('hired', '==', false),
        limit(1)
      );
      const unsubscribe = onSnapshot(notificationsQuery, (snapshot) => {
        setHasNewApplications(snapshot.size > 0);
      });
      return () => unsubscribe();
    }
  }, [user.companyId]);

  // Räkna ut användarens initialer
  const getUserInitials = () => {
    if (!user.name) return '';
    return user.name.split(' ').map(n => n[0]).join('').toUpperCase();
  };

  // Kolla fönsterbredden för att avgöra om vi är på mobil
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);
  useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);
  const isMobile = windowWidth < 768;

  return (
    <div className={`dashboard-container ${sidebarOpen ? 'sidebar-open' : 'sidebar-closed'}`}>
      {/* Desktop-vy: Visa sidebaren */}
      {!isMobile && (
        <div className={`sidebar ${sidebarOpen ? 'open' : 'closed'}`}>
          <div className="sidebar-header">
            <div className="hamburger-container">
              <button className="hamburger-button" onClick={() => setSidebarOpen(!sidebarOpen)}>
                {sidebarOpen ? <FaTimes className="hamburger-icon" /> : <FaBars className="hamburger-icon" />}
              </button>
            </div>
            {sidebarOpen && (
              <div className="logo-container">
                <img src={vitLogo} alt="QwioJobs logo" className="sidebar-logo" />
                <h2 className="sidebar-title">
                  {isSuperAdmin ? 'SuperAdmin Panel' : 'QwioJobs'}
                </h2>
              </div>
            )}
          </div>

          {sidebarOpen && (
            <>
              <ul>
                <li>
                  <a
                    href="#!"
                    className={selectedMenu === 'dashboard' ? 'active' : ''}
                    onClick={(e) => {
                      e.preventDefault();
                      setSelectedMenu('dashboard');
                    }}
                  >
                    Dashboard
                  </a>
                </li>
                {isSuperAdmin && (
                  <>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'manage-companies' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('manage-companies');
                        }}
                      >
                        Hantera Företag
                      </a>
                    </li>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'manage-users' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('manage-users');
                        }}
                      >
                        Hantera Användare
                      </a>
                    </li>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'settings' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('settings');
                        }}
                      >
                        Inställningar
                      </a>
                    </li>
                  </>
                )}
                {(isAdmin || isUser) && (
                  <>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'published-jobs' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('published-jobs');
                        }}
                      >
                        Publicerade jobb
                      </a>
                    </li>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'job-applications' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('job-applications');
                        }}
                      >
                        Kandidater
                        {hasNewApplications && (
                          <div className="sidebar-notification-bell">
                            <FaBell className="bell-icon" />
                            <span className="tooltip">Nya ansökningar</span>
                          </div>
                        )}
                      </a>
                    </li>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'settings' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('settings');
                        }}
                      >
                        Inställningar
                      </a>
                    </li>
                  </>
                )}
              </ul>
              <div className="user-info">
                <div className="user-avatar">{getUserInitials()}</div>
                <p>{user.email}</p>
                <button onClick={handleLogout} className="logout-button">Logga ut</button>
              </div>
            </>
          )}
        </div>
      )}

      {/* Mobil-vy: Visa fast header och mobilmeny */}
      {isMobile && (
        <>
          <div className="mobile-header">
            <div className="mobile-logo">
              <img src={vitLogo} alt="QwioJobs logo" className="mobile-logo-img" />
              <h2 className="mobile-title">
                {isSuperAdmin ? 'SuperAdmin Panel' : 'QwioJobs'}
              </h2>
            </div>
            <div className="mobile-hamburger">
              <button onClick={() => setSidebarOpen(!sidebarOpen)}>
                {sidebarOpen ? <FaTimes /> : <FaBars />}
              </button>
            </div>
          </div>
          {sidebarOpen && (
            <div className="mobile-menu">
              <ul>
                <li>
                  <a
                    href="#!"
                    className={selectedMenu === 'dashboard' ? 'active' : ''}
                    onClick={(e) => {
                      e.preventDefault();
                      setSelectedMenu('dashboard');
                      setSidebarOpen(false);
                    }}
                  >
                    Dashboard
                  </a>
                </li>
                {isSuperAdmin && (
                  <>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'manage-companies' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('manage-companies');
                          setSidebarOpen(false);
                        }}
                      >
                        Hantera Företag
                      </a>
                    </li>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'manage-users' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('manage-users');
                          setSidebarOpen(false);
                        }}
                      >
                        Hantera Användare
                      </a>
                    </li>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'settings' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('settings');
                          setSidebarOpen(false);
                        }}
                      >
                        Inställningar
                      </a>
                    </li>
                  </>
                )}
                {(isAdmin || isUser) && (
                  <>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'published-jobs' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('published-jobs');
                          setSidebarOpen(false);
                        }}
                      >
                        Publicerade jobb
                      </a>
                    </li>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'job-applications' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('job-applications');
                          setSidebarOpen(false);
                        }}
                      >
                        Kandidater
                        {hasNewApplications && (
                          <div className="sidebar-notification-bell">
                            <FaBell className="bell-icon" />
                            <span className="tooltip">Nya ansökningar</span>
                          </div>
                        )}
                      </a>
                    </li>
                    <li>
                      <a
                        href="#!"
                        className={selectedMenu === 'settings' ? 'active' : ''}
                        onClick={(e) => {
                          e.preventDefault();
                          setSelectedMenu('settings');
                          setSidebarOpen(false);
                        }}
                      >
                        Inställningar
                      </a>
                    </li>
                  </>
                )}
              </ul>
              <div className="user-info">
                <div className="user-avatar">{getUserInitials()}</div>
                <p>{user.email}</p>
                <button onClick={handleLogout} className="logout-button">Logga ut</button>
              </div>
            </div>
          )}
        </>
      )}

      <div className={`content ${sidebarOpen ? 'sidebar-open' : 'sidebar-closed'}`}>
        {selectedMenu === 'dashboard' && (
          <>
            <h1>Välkommen, {user.name} 😊</h1>
            {(isAdmin || isUser) && <DashboardStats user={user} />}
            {isSuperAdmin && <SuperAdminDashboard />}
          </>
        )}

        {selectedMenu === 'published-jobs' && (isAdmin || isUser) && <PublishedJobs user={user} />}
        
        {selectedMenu === 'job-applications' && (isAdmin || isUser) && (
          // Vi skickar nu en no-op-funktion eftersom realtime‑lyssnaren i Dashboard hanterar notifikationerna
          <JobApplications 
            user={user} 
            refreshUnopenedCount={() => {}}
          />
        )}

        {isSuperAdmin && selectedMenu === 'manage-companies' && <ManageCompanies />}
        {isSuperAdmin && selectedMenu === 'manage-users' && <ManageUsers />}
        {selectedMenu === 'settings' && (isAdmin || isUser) && <Settings user={user} />}
        {isSuperAdmin && selectedMenu === 'settings' && <SuperSettings user={user} />}
      </div>
    </div>
  );
}

export default Dashboard;
