import React, { useState } from 'react';
import { signInWithEmailAndPassword, sendPasswordResetEmail } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { auth, db } from './firebase';
import Dashboard from './Dashboard';
import { FaEye, FaEyeSlash } from 'react-icons/fa';
import logo from '../img/QWIO-9.png';
import './LoginPage.css';

function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [user, setUser] = useState(null);
  const [error, setError] = useState('');

  // State för lösenordsåterställning
  const [showResetModal, setShowResetModal] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [resetMessage, setResetMessage] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const loggedInUser = userCredential.user;

      console.log('Inloggad UID:', loggedInUser.uid);

      // Hämta användardata från Firestore
      const userDoc = await getDoc(doc(db, 'users', loggedInUser.uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        console.log('Användardata hittad:', userData);

        if (userData.role === 'user') {
          const companyDoc = await getDoc(doc(db, `companies/${userData.companyId}`));
          if (companyDoc.exists()) {
            console.log('Företagsdata hittad:', companyDoc.data());
            setUser({
              ...userData,
              companyName: companyDoc.data().name,
            });
          } else {
            setError('Företaget kunde inte hittas.');
          }
        } else {
          setUser({ ...userData });
        }
      } else {
        setError('Användaren kunde inte hittas.');
      }
    } catch (err) {
      console.error('Inloggningsfel:', err.message);
      setError('Inloggningen misslyckades. Kontrollera dina uppgifter.');
    }
  };

  const handlePasswordReset = async (e) => {
    e.preventDefault();
    setResetMessage('');
    try {
      await sendPasswordResetEmail(auth, resetEmail);
      setResetMessage('Återställningslänk har skickats till din e-postadress.');
    } catch (error) {
      console.error('Fel vid lösenordsåterställning:', error.message);
      setResetMessage('Något gick fel. Var god försök igen.');
    }
  };

  return user ? (
    <Dashboard user={user} handleLogout={() => setUser(null)} />
  ) : (
    <div className="login-container">
      <div className="login-form">
        <div className="logo-container">
          <img className="floating-logo" src={logo} alt="QWIO logga" width="120" />
          <h1 className="logo-text">QwioJobs</h1>
        </div>

        <form onSubmit={handleLogin}>
          <input
            type="email"
            placeholder="E-post"
            className="input-field"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <div className="password-container">
            <input
              type={showPassword ? 'text' : 'password'}
              placeholder="Lösenord"
              className="input-field password-field"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
            <span
              className="toggle-password"
              onClick={() => setShowPassword(!showPassword)}
            >
              {showPassword ? <FaEyeSlash /> : <FaEye />}
            </span>
          </div>
          <button type="submit" className="login-button">
            Logga in
          </button>
        </form>
        {error && <p className="error-message">{error}</p>}
        <p className="forgot-password">
          Har du glömt ditt lösenord?
          <button
            className="forgot-password-link"
            onClick={() => setShowResetModal(true)}
          >
            Klicka här
          </button>
        </p>
      </div>

      {/* Modal för lösenordsåterställning */}
      {showResetModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h2>Återställ lösenord</h2>
            <form onSubmit={handlePasswordReset}>
              <input
                type="email"
                placeholder="Ange din e-postadress"
                className="input-field"
                value={resetEmail}
                onChange={(e) => setResetEmail(e.target.value)}
                required
              />
              <button type="submit" className="login-button">
                Skicka återställningslänk
              </button>
            </form>
            {resetMessage && <p className="reset-message">{resetMessage}</p>}
            <button
              className="close-modal"
              onClick={() => {
                setShowResetModal(false);
                setResetEmail('');
                setResetMessage('');
              }}
            >
              Stäng
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default LoginPage;
