import React, { useState } from 'react';
import { auth, db } from './firebase';
import { 
  createUserWithEmailAndPassword, 
  reauthenticateWithCredential, 
  EmailAuthProvider, 
  updatePassword 
} from 'firebase/auth';
import { collection, addDoc } from 'firebase/firestore';
import './SuperSettings.css';

function SuperSettings({ user }) {
  // State för att lägga till superadmin
  const [addEmail, setAddEmail] = useState('');
  const [addFirstName, setAddFirstName] = useState('');
  const [addLastName, setAddLastName] = useState('');
  const [addPassword, setAddPassword] = useState('');
  const [addError, setAddError] = useState('');
  const [addSuccess, setAddSuccess] = useState('');

  // State för att byta lösenord
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passError, setPassError] = useState('');
  const [passSuccess, setPassSuccess] = useState('');

  // Funktion för att lägga till en superadmin
  const handleAddSuperAdmin = async (e) => {
    e.preventDefault();
    setAddError('');
    setAddSuccess('');
    if (!addEmail || !addFirstName || !addLastName || !addPassword) {
      setAddError('Alla fält måste fyllas i.');
      return;
    }
    try {
      // Skapa användare i Firebase Auth
      const userCredential = await createUserWithEmailAndPassword(auth, addEmail, addPassword);
      // Lägg till övriga uppgifter i Firestore (t.ex. i en "users" collection)
      await addDoc(collection(db, 'users'), {
        uid: userCredential.user.uid,
        email: addEmail,
        firstName: addFirstName,
        lastName: addLastName,
        role: 'superadmin'
      });
      setAddSuccess('Superadmin skapad!');
      // Rensa formuläret
      setAddEmail('');
      setAddFirstName('');
      setAddLastName('');
      setAddPassword('');
    } catch (error) {
      setAddError(error.message);
    }
  };

  // Funktion för att byta lösenord
  const handleChangePassword = async (e) => {
    e.preventDefault();
    setPassError('');
    setPassSuccess('');
    if (!currentPassword || !newPassword || !confirmPassword) {
      setPassError('Alla fält måste fyllas i.');
      return;
    }
    if (newPassword !== confirmPassword) {
      setPassError('Nytt lösenord och bekräftelse matchar inte.');
      return;
    }
    try {
      // Reautentisera den nuvarande användaren
      const credential = EmailAuthProvider.credential(user.email, currentPassword);
      await reauthenticateWithCredential(auth.currentUser, credential);
      // Uppdatera lösenordet
      await updatePassword(auth.currentUser, newPassword);
      setPassSuccess('Lösenord uppdaterat!');
      // Rensa formuläret
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
    } catch (error) {
      setPassError(error.message);
    }
  };

  return (
    <div className="super-settings">
      <h2>Superinställningar</h2>
      
      <div className="section">
        <h3>Lägg till Super Admin</h3>
        <form onSubmit={handleAddSuperAdmin}>
          <div className="form-group">
            <label>Email:</label>
            <input 
              type="email" 
              value={addEmail} 
              onChange={(e) => setAddEmail(e.target.value)} 
            />
          </div>
          <div className="form-group">
            <label>Förnamn:</label>
            <input 
              type="text" 
              value={addFirstName} 
              onChange={(e) => setAddFirstName(e.target.value)} 
            />
          </div>
          <div className="form-group">
            <label>Efternamn:</label>
            <input 
              type="text" 
              value={addLastName} 
              onChange={(e) => setAddLastName(e.target.value)} 
            />
          </div>
          <div className="form-group">
            <label>Lösenord:</label>
            <input 
              type="password" 
              value={addPassword} 
              onChange={(e) => setAddPassword(e.target.value)} 
            />
          </div>
          {addError && <p className="error">{addError}</p>}
          {addSuccess && <p className="success">{addSuccess}</p>}
          <button type="submit">Skapa Super Admin</button>
        </form>
      </div>

      <div className="section">
        <h3>Byt Lösenord</h3>
        <form onSubmit={handleChangePassword}>
          <div className="form-group">
            <label>Nuvärande Lösenord:</label>
            <input 
              type="password" 
              value={currentPassword} 
              onChange={(e) => setCurrentPassword(e.target.value)} 
            />
          </div>
          <div className="form-group">
            <label>Nytt Lösenord:</label>
            <input 
              type="password" 
              value={newPassword} 
              onChange={(e) => setNewPassword(e.target.value)} 
            />
          </div>
          <div className="form-group">
            <label>Bekräfta Nytt Lösenord:</label>
            <input 
              type="password" 
              value={confirmPassword} 
              onChange={(e) => setConfirmPassword(e.target.value)} 
            />
          </div>
          {passError && <p className="error">{passError}</p>}
          {passSuccess && <p className="success">{passSuccess}</p>}
          <button type="submit">Byt Lösenord</button>
        </form>
      </div>
    </div>
  );
}

export default SuperSettings;
